#include<iostream>
#include<sstream>
#include<vector>
#include<algorithm>
#include<unordered_map>
using namespace std;
​
int main()
{
    string s;
    getline(cin, s);
    int n = s.length();
    // [-1,2,4,9,6] => -1,2,4,9,6
    string str = s.substr(1, n - 2);
    // 按,分割字符串
    stringstream path(str);
    string token;
    vector<int> nums;
    while (getline(path, token, ','))
    {
        nums.push_back(stoi(token));
    }
​
    int target;
    cin >> target;

    int minIdxSum = nums.size() * 2;
    // 记录 target - num 出现的最小索引
    unordered_map<int, int> hashDic;
    vector<int> ans(2);
​
    for (int i = 0; i < nums.size(); i++)
    {
        int num = nums[i];
        int restNum = target - num;
        if (hashDic.find(restNum) != hashDic.end())
        {
            // 选取索引和小的
            if (minIdxSum > hashDic[restNum] + i)
            {
                minIdxSum = hashDic[restNum] + i;
                ans[0] = restNum;
                ans[1] = num;
            }
        }
​
        if (hashDic.find(num) == hashDic.end())
        {
            hashDic[num] = i;
        }
    }
    // 输出结果
    cout << "[" << ans[0] << ", " << ans[1] << "]" << endl;
    return 0;
​
}

