import java.util.*;
​
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine().trim();
        int target = scanner.nextInt();
​
        // 解析输入字符串，去除方括号，并按逗号分割
        String str = s.substring(1, s.length() - 1);
        String[] tokens = str.split(",");
        int[] nums = new int[tokens.length];
​
        for (int i = 0; i < tokens.length; i++) {
            nums[i] = Integer.parseInt(tokens[i].trim());
        }
​
        // 哈希表记录 target - num 出现的最小索引
        Map<Integer, Integer> hashMap = new HashMap<>();
        int minIdxSum = nums.length * 2;
        int[] ans = new int[2];
​
        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            int restNum = target - num;
​
            if (hashMap.containsKey(restNum)) {
                if (minIdxSum > hashMap.get(restNum) + i) {
                    minIdxSum = hashMap.get(restNum) + i;
                    ans[0] = restNum;
                    ans[1] = num;
                }
            }
​
            if (!hashMap.containsKey(num)) {
                hashMap.put(num, i);
            }
        }
​
        System.out.println("[" + ans[0] + ", " + ans[1] + "]");
        scanner.close();
    }
}
