const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let input = [];
​
rl.on('line', (line) => {
    input.push(line.trim());
    if (input.length === 2) {
        rl.close();
    }
});
​
rl.on('close', () => {
    let s = input[0];
    let target = parseInt(input[1]);
​
    // 解析数组字符串并转换为整数数组
    let nums = s.slice(1, -1).split(',').map(num => parseInt(num.trim()));
​
    // 记录 target - num 出现的最小索引
    let hashMap = new Map();
    let minIdxSum = nums.length * 2;
    let ans = [0, 0];
​
    for (let i = 0; i < nums.length; i++) {
        let num = nums[i];
        let restNum = target - num;

        if (hashMap.has(restNum)) {
            if (minIdxSum > hashMap.get(restNum) + i) {
                minIdxSum = hashMap.get(restNum) + i;
                ans = [restNum, num];
            }
        }
​
        if (!hashMap.has(num)) {
            hashMap.set(num, i);
        }
    }
​
    console.log(`[${ans[0]}, ${ans[1]}]`);
});
