package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    // 读取输入
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    s := scanner.Text()
    scanner.Scan()
    target, _ := strconv.Atoi(scanner.Text())
​
    // 解析字符串，转换为整数数组
    s = strings.Trim(s, "[]")
    numStrs := strings.Split(s, ",")
    nums := make([]int, len(numStrs))
    for i, numStr := range numStrs {
        nums[i], _ = strconv.Atoi(strings.TrimSpace(numStr))
    }
​
    // 记录 target - num 出现的最小索引
    hashMap := make(map[int]int)
    minIdxSum := len(nums) * 2
    ans := [2]int{}
​
    for i, num := range nums {
        restNum := target - num
​
        if index, found := hashMap[restNum]; found {
            if minIdxSum > index+i {
                minIdxSum = index + i
                ans[0], ans[1] = restNum, num
            }
        }
​
        if _, exists := hashMap[num]; !exists {
            hashMap[num] = i
        }
    }
​
    fmt.Printf("[%d, %d]\n", ans[0], ans[1])
}
